def solve(payload):
    import re
    results = []
    for original in payload["paths"]:
        path = original.replace("\\", "/")
        if path.startswith("/") or re.match(r"^[A-Za-z]:", path) or any(ord(ch) < 32 or ord(ch) == 127 for ch in path):
            results.append(None)
            continue
        parts = []
        rejected = False
        for part in path.split("/"):
            if part in ("", "."):
                continue
            if part == "..":
                if not parts:
                    rejected = True
                    break
                parts.pop()
            else:
                parts.append(part)
        results.append(None if rejected else "/".join(parts) or ".")
    return {"normalized": results}

